const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const startDate = '2016-08-01';
    const endDate = '2018-02-28';

    // Load FAO GAUL country boundaries
    const countries = ee.FeatureCollection('FAO/GAUL/2015/level0');

    // Get Cambodia and Thailand geometries
    const cambodia = countries.filter(ee.Filter.eq('ADM0_NAME', 'Cambodia'));
    const thailand = countries.filter(ee.Filter.eq('ADM0_NAME', 'Thailand'));

    // Check if country geometries are found
    if (cambodia.size().getInfo() === 0 || thailand.size().getInfo() === 0) {
      console.log("Error: Could not find country boundaries for Cambodia or Thailand.");
      console.log("C3"); // Calculation failure due to missing geometry
      return;
    }

    const cambodiaGeom = cambodia.geometry();
    const thailandGeom = thailand.geometry();

    // 2. Data Acquisition & Check
    // Using MODIS/061/MCD14DL for active fire detections (daily data)
    let firmsCollection = ee.ImageCollection('MODIS/061/MCD14DL')
      .filterDate(startDate, endDate);

    // Initial check for data availability
    if (firmsCollection.size().getInfo() === 0) {
      console.log("No active fire data found for the specified date range.");
      console.log("C1");
      return;
    }

    // 3. Processing & Calculation
    // Filter fire detections by country boundaries and count them
    const cambodiaFires = firmsCollection.filterBounds(cambodiaGeom).size().getInfo();
    const thailandFires = firmsCollection.filterBounds(thailandGeom).size().getInfo();

    // Check for calculation failure (e.g., if getInfo() somehow returns null/NaN, though unlikely for size())
    if (cambodiaFires === null || thailandFires === null) {
      console.log("Calculation of fire counts failed (returned null).");
      console.log("C3");
      return;
    }

    // A count of 0 is a valid result, meaning no fires were detected.
    // So, C2 (No Valid Pixels) is not applicable here as 0 fires is meaningful.

    // 4. Validation & Final Answer
    console.log(`Active fire detections in Cambodia (${startDate} to ${endDate}): ${cambodiaFires}`);
    console.log(`Active fire detections in Thailand (${startDate} to ${endDate}): ${thailandFires}`);

    if (cambodiaFires > thailandFires) {
      console.log("A");
    } else {
      console.log("B");
    }

  } catch (error) {
    console.error("An error occurred during the analysis:", error);
    if (error.message.includes("does not exist") || error.message.includes("Invalid band")) {
      console.log("D"); // e.g., incorrect collection or band name
    } else {
      console.log("C3"); // Other calculation failures or unexpected errors
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
